import{_ as e,a,b as o,c as i}from"./chunks/state-monitoring-4.Bpnw36H5.js";import{_ as n,o as r,c as s,a5 as l}from"./chunks/framework.CcrBcQWS.js";const b=JSON.parse('{"title":"State Monitoring","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/state-monitoring.md","filePath":"manual/gui/state-monitoring.md","lastUpdated":1787021357000}'),c={name:"manual/gui/state-monitoring.md"};function g(p,t,u,m,h,d){return r(),s("div",null,[...t[0]||(t[0]=[l('<h1 id="state-monitoring" tabindex="-1">State Monitoring <a class="header-anchor" href="#state-monitoring" aria-label="Permalink to &quot;State Monitoring&quot;">​</a></h1><p>In RBQGUI, you can check the robot’s current status (emergency/power/sensors/perception modules) in real time.</p><h2 id="_1-top-status-area" tabindex="-1">1) Top Status Area <a class="header-anchor" href="#_1-top-status-area" aria-label="Permalink to &quot;1) Top Status Area&quot;">​</a></h2><p>You can check the <code>EMERGENCY</code> status and various system status icons (battery/connection/power, etc.) at a glance.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+e+'" alt="Top status area" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Top status area</figcaption></figure><h2 id="_2-diagnostic-table-motors-imu-etc" tabindex="-1">2) Diagnostic Table (Motors/IMU, etc.) <a class="header-anchor" href="#_2-diagnostic-table-motors-imu-etc" aria-label="Permalink to &quot;2) Diagnostic Table (Motors/IMU, etc.)&quot;">​</a></h2><p>Review diagnostic values per leg/joint (e.g., HRR/HRP/...) along with temperature, gyro, and acceleration (ACC) readings in a table.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+a+'" alt="Diagnostic table" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Joint/Sensor diagnostic table</figcaption></figure><h3 id="joint-naming" tabindex="-1">Joint Naming <a class="header-anchor" href="#joint-naming" aria-label="Permalink to &quot;Joint Naming&quot;">​</a></h3><p>Joint IDs in the diagnostic table use the following abbreviations:</p><ul><li><strong>HRR</strong> : Hind Right Roll, <strong>HRP</strong> : Hind Right Pitch, <strong>HRK</strong> : Hind Right Knee</li><li><strong>HLR</strong> : Hind Left Roll, <strong>HLP</strong> : Hind Left Pitch, <strong>HLK</strong> : Hind Left Knee</li><li><strong>FRR</strong> : Front Right Roll, <strong>FRP</strong> : Front Right Pitch, <strong>FRK</strong> : Front Right Knee</li><li><strong>FLR</strong> : Front Left Roll, <strong>FLP</strong> : Front Left Pitch, <strong>FLK</strong> : Front Left Knee</li></ul><h2 id="_3-perception-status" tabindex="-1">3) Perception Status <a class="header-anchor" href="#_3-perception-status" aria-label="Permalink to &quot;3) Perception Status&quot;">​</a></h2><p>Check the ON/OFF state and operation status, errors, and Fail/Count information for perception-related modules such as the IR projector, night vision, and LED buzzer.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+o+'" alt="Perception status" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Perception module status</figcaption></figure><h2 id="_4-power-switch-module-check" tabindex="-1">4) Power Switch &amp; Module Check <a class="header-anchor" href="#_4-power-switch-module-check" aria-label="Permalink to &quot;4) Power Switch &amp; Module Check&quot;">​</a></h2><p>You can check power switch states (Vision Computer/Cameras/sensors such as LiDAR) and review major power/load status like BAT/LEGS/ADDON/EXTERN/CHARGE. Press the button to refresh the status.</p><figure style="margin-top:1rem;text-align:center;"><img src="'+i+'" alt="Power switch and module check" style="display:block;margin:0 auto;"><figcaption style="text-align:center;margin-top:0.5rem;color:var(--vp-c-text-2, #666);font-size:0.95em;">Power switch &amp; module check</figcaption></figure><h2 id="notes-warnings" tabindex="-1">Notes / Warnings <a class="header-anchor" href="#notes-warnings" aria-label="Permalink to &quot;Notes / Warnings&quot;">​</a></h2><ul><li>If <code>EMERGENCY</code> or an abnormal state is shown, secure safety first and then check the cause (sensor/power/perception module operation, etc.).</li><li>If perception/sensor modules are OFF, the corresponding features (e.g., vision-based walking) may be limited.</li></ul>',19)])])}const R=n(c,[["render",g]]);export{b as __pageData,R as default};
